class BankAccount{private String acc;private String holder;private double balance;static int totalAccounts;BankAccount(String a,String h,double b){acc=a;holder=h;balance=b;totalAccounts++;}void deposit(double a){balance+=a;}void withdraw(double a){if(a<=balance)balance-=a;}} public class BankAccountDemo{public static void main(String[]args){BankAccount b=new BankAccount("A1","Sameer",1000);b.deposit(500);}}